// V2-3n: integrate each actual room's rectangular aperture with the same
// microfilter, instead of assigning every filtered contribution to floor(grid).
vec3 window_emission_at(
    vec2 grid, vec2 room_parallax, vec4 pane_bounds, vec2 antialias,
    float occupancy_threshold, float style
) {
    vec2 first_cell = floor(grid - antialias);
    vec2 last_cell = floor(grid + antialias);
    vec3 result = vec3(0.0);
    // AA <= 0.12, so at most two source cells overlap in either axis.
    for (int y = 0; y < 2; ++y) {
        for (int x = 0; x < 2; ++x) {
            vec2 cell = first_cell + vec2(float(x), float(y));
            if (cell.x > last_cell.x || cell.y > last_cell.y) continue;
            result += window_emission_in_cell(
                grid, cell, room_parallax, pane_bounds, antialias,
                occupancy_threshold, style
            );
        }
    }
    return result;
}

